function Field({row,name,change,options,title}:{row:Row;name:string;change:(v:Row)=>void;options?:string[];title?:string}) {
  const v = row[name] ?? '';
  const [custom,setCustom]=useState(false);
  const builtin:Record<string,string[]>={fapiaoType:FAPIAO_TYPES,vatRate:VAT_RATES,refundRate:REFUND_RATES,cargoDocumentsStatus:CARGO_STATUS,transportMethod:TRANSPORT,packageType:PACKAGING,paymentTerms:PAYMENT_TERMS,taxpayerType:['','General VAT taxpayer / 一般纳税人','Small-scale taxpayer / 小规模纳税人','Other / 其他'],taxTreatment:['Not reviewed','Pending','Accountant confirmed refund / 会计确认退税','Accountant confirmed exemption / 会计确认免税','Accountant confirmed taxable / 会计确认征税','Other reviewed treatment / 其他已核实处理'],exportType:['Self-operated','Entrusted'],unit:['pcs','sets','kg','g','tonnes','m','m²','m³','cartons','pairs','rolls','lots','units'],preferredCurrency:currencies};
  const choice=builtin[name]||options;
  const percent=name==='vatRate'||name==='refundRate';
  if (typeof v === 'boolean') return <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={v} onChange={e=>change({...row,[name]:e.target.checked})}/>{title?title+(chineseLabels[name]?' / '+chineseLabels[name]:''):label(name)}</label>;
  return <label className="block space-y-1 text-sm"><span className="font-medium">{title?title+(chineseLabels[name]?' / '+chineseLabels[name]:''):label(name)}</span>{choice?<><select className={input} value={custom?'__custom':String(v)} onChange={e=>{const val=e.target.value;if(val==='__custom'){setCustom(true);return;}setCustom(false);change({...row,[name]:typeof v==='number'||percent?Number(val):val});}}>{!choice.includes('')&&typeof v!=='number'&&<option value="">Select / 请选择</option>}{!choice.includes(String(v))&&String(v)&&<option value={String(v)}>{String(v)}</option>}{choice.map(o=><option key={o} value={o}>{o?(percent?o+'%':o):'Select / 请选择'}</option>)}{name!=='currency'&&<option value="__custom">Other / custom / 自定义</option>}</select>{custom&&<input className={input} type={percent||typeof v==='number'?'number':'text'} min={percent?0:undefined} max={percent?100:undefined} step={percent?'any':undefined} value={String(v)} onChange={e=>change({...row,[name]:percent||typeof v==='number'?Number(e.target.value):e.target.value})}/>}</>:<input className={input} value={String(v)} type={typeof v==='number'?'number':/date$/i.test(name)?'date':/email$/i.test(name)?'email':/phone$/i.test(name)?'tel':'text'} min={typeof v==='number'?0:undefined} step={typeof v==='number'?'any':undefined} onChange={e=>change({...row,[name]:typeof v==='number'?Number(e.target.value):e.target.value})}/>}</label>;
}
function Grid({children}:{children:ReactNode}) {return <div className="grid gap-3 sm:grid-cols-2">{children}</div>}
function Checks({items,checked,change}:{items:string[];checked:string[];change:(v:string[])=>void}) {return <div className="space-y-2">{items.map(item=><label key={item} className="flex items-start gap-3 rounded-lg border p-3 text-sm"><input className="mt-1" type="checkbox" checked={checked.includes(item)} onChange={e=>change(e.target.checked?[...checked,item]:checked.filter(i=>i!==item))}/>{item}</label>)}</div>}
function downloadCsv(entries:Row[],demo=false) {
  const safe=(v:unknown)=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
  const fields=['date','category','description','currency','amount','rate','hsCode','declaration','vatRate','refundRate','fapiaoNumber','fapiaoDate','fapiaoIssuer','fapiaoType','fapiaoVerifiedDate','fapiao','fxMemo'];
  const csv=[fields.concat('amountCny').join(','),...entries.map(r=>[...fields.map(f=>safe(r[f])),safe(rmb(r).toFixed(2))].join(','))].join('\r\n');
  const url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=(demo?'SAMPLE-':'')+'module-2-ledger.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

