  const chartBars=[{label:'Export receipts',value:revenue,color:'#10b981'},{label:'Procurement',value:d.entries.filter(r=>r.category==='procurement').reduce((a,r)=>a+rmb(r),0),color:'#f59e0b'},{label:'Customs / freight',value:d.entries.filter(r=>r.category==='customs_freight').reduce((a,r)=>a+rmb(r),0),color:'#6366f1'},{label:'Operating',value:d.entries.filter(r=>r.category==='operating').reduce((a,r)=>a+rmb(r),0),color:'#94a3b8'},{label:'VAT received',value:received,color:'#0891b2'},{label:'Estimated VAT',value:estimated,color:'#8b5cf6'}];
